169	    /**
170	     * The stored E.164 {@link #telephone} formatted for humans as the country code, a single
171	     * space, then the national digits (the digits after the country code) grouped in threes from
172	     * the left, e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}. The country code is
173	     * a single digit for the {@code +1} and {@code +7} zones and two digits otherwise.
174	     *
175	     * @return the human-formatted telephone, or the raw {@link #telephone} unchanged when it is
176	     *         {@code null} or not a {@code +} followed by digits
177	     */
178	    public String getTelephoneDisplay() {
179	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
180	            return this.telephone;
181	        }
182	        String digits = this.telephone.substring(1);
183	        int countryCodeLength = ONE_DIGIT_CALLING_CODES.contains(digits.substring(0, 1)) ? 1 : 2;
184	        if (digits.length() <= countryCodeLength) {
185	            return this.telephone;
186	        }
187	        String countryCode = digits.substring(0, countryCodeLength);
188	        String national = digits.substring(countryCodeLength);
189	        StringBuilder grouped = new StringBuilder();
190	        for (int i = 0; i < national.length(); i++) {
191	            if (i > 0 && i % 3 == 0) {
192	                grouped.append(' ');
193	            }
194	            grouped.append(national.charAt(i));
195	        }
196	        return "+" + countryCode + " " + grouped;
197	    }
