424	    /**
425	     * The fiscal year of the (business-day-adjusted) {@link #registrationDate}, formatted as
426	     * {@code "FY<YY>"}. The fiscal year starts on 1 July: a registration date on or after 1 July
427	     * belongs to that calendar year's fiscal year, an earlier date belongs to the previous year's,
428	     * and {@code YY} is the last two digits of the year the fiscal year started (e.g. a date in
429	     * August 2026 yields {@code "FY26"}, a date in March 2026 yields {@code "FY25"}).
430	     *
431	     * @return the formatted fiscal year, or {@code null} if the registration date has not been
432	     *         assigned
433	     */
434	    public String getFiscalYear() {
435	        if (this.registrationDate == null) {
436	            return null;
437	        }
438	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
439	    }
440	
441	    /**
442	     * The starting calendar year of the fiscal year (which begins on 1 July) that the given date
443	     * falls in: the date's own year when it is on or after 1 July, otherwise the previous year.
444	     *
445	     * @param date the date whose fiscal year is derived (must not be {@code null})
446	     * @return the starting calendar year of the fiscal year
447	     */
448	    private static int fiscalYearOf(LocalDate date) {
449	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
450	            ? date.getYear() : date.getYear() - 1;
451	    }
