583	    /**
584	     * The owner's segment, formatted {@code "<TIER>_<AREA>"}, one of {@code "PREMIUM_METRO"},
585	     * {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or {@code "STANDARD_REGIONAL"}. The tier
586	     * is {@code "PREMIUM"} when the {@link #getMembershipLevel() membership level} is {@code 3} or
587	     * more, otherwise {@code "STANDARD"}. The area is {@code "METRO"} when the
588	     * {@link #getLocality() locality} is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
589	     * otherwise {@code "REGIONAL"}.
590	     *
591	     * @return the formatted owner segment
592	     */
593	    public String getOwnerSegment() {
594	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
595	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
596	        return tier + "_" + area;
597	    }
598	
599	    /**
600	     * The owner's identity key: the single derived value used for duplicate detection. It is the
601	     * lower-case, 64-character hex SHA-256 digest over
602	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}, where the telephone
603	     * is the already-normalized stored value, the email is lower-cased (a {@code null} email is
604	     * rendered as the empty string) and the last name is reduced to its Soundex code. Two owners are
605	     * duplicates only when their whole identity keys are equal; because the telephone is part of the
606	     * key, two owners sharing a last name (Soundex) but with different telephones have different
607	     * identity keys and so are not hard duplicates.
608	     *
609	     * @return the derived identity key
610	     */
611	    public String getIdentityKey() {
612	        String telephonePart = this.telephone == null ? "" : this.telephone;
613	        String emailPart = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
614	        String soundexPart = soundex(getLastName());
615	        return sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
616	    }
617	
618	    /**
619	     * Returns the lower-case, 64-character hex SHA-256 digest of the UTF-8 bytes of {@code input}.
620	     *
621	     * @param input the value to hash
622	     * @return the full hex digest
623	     */
624	    private static String sha256Hex(String input) {
625	        try {
626	            byte[] digest = MessageDigest.getInstance("SHA-256")
627	                .digest(input.getBytes(StandardCharsets.UTF_8));
628	            StringBuilder sb = new StringBuilder(digest.length * 2);
629	            for (byte b : digest) {
630	                sb.append(String.format("%02x", b));
631	            }
632	            return sb.toString();
633	        }
634	        catch (NoSuchAlgorithmException e) {
635	            throw new IllegalStateException("SHA-256 not available", e);
636	        }
637	    }
638	
639	    /**
640	     * Computes the American Soundex code of a name: the first letter followed by three digits that
641	     * phonetically encode the remaining consonants. Non-letters are ignored, {@code h} and {@code w}
642	     * are transparent (letters either side of them are treated as adjacent) and vowels reset the
643	     * run so a repeated code across a vowel is encoded twice. A {@code null} or letter-free value
644	     * yields the empty string.
645	     *
646	     * @param value the name to encode
647	     * @return the Soundex code, or the empty string when there is no letter to encode
648	     */
649	    public static String soundex(String value) {
650	        if (value == null) {
651	            return "";
652	        }
653	        StringBuilder letters = new StringBuilder();
654	        for (int i = 0; i < value.length(); i++) {
655	            char c = Character.toUpperCase(value.charAt(i));
656	            if (c >= 'A' && c <= 'Z') {
657	                letters.append(c);
658	            }
659	        }
660	        if (letters.length() == 0) {
661	            return "";
662	        }
663	        StringBuilder code = new StringBuilder();
664	        char first = letters.charAt(0);
665	        code.append(first);
666	        char last = soundexDigit(first);
667	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
668	            char c = letters.charAt(i);
669	            if (c == 'H' || c == 'W') {
670	                // Transparent: leave the previous code in place so letters either side stay adjacent.
671	                continue;
672	            }
673	            char digit = soundexDigit(c);
674	            if (digit != '0') {
675	                if (digit != last) {
676	                    code.append(digit);
677	                }
678	                last = digit;
679	            }
680	            else {
681	                // A vowel breaks the run so a following letter with the same code is encoded again.
682	                last = '0';
683	            }
684	        }
685	        while (code.length() < 4) {
686	            code.append('0');
687	        }
688	        return code.toString();
689	    }
690	
691	    /**
692	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for vowels and the
693	     * uncoded letters {@code h} and {@code w}.
694	     */
695	    private static char soundexDigit(char c) {
696	        switch (c) {
697	            case 'B': case 'F': case 'P': case 'V':
698	                return '1';
699	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
700	                return '2';
701	            case 'D': case 'T':
702	                return '3';
703	            case 'L':
704	                return '4';
705	            case 'M': case 'N':
706	                return '5';
707	            case 'R':
708	                return '6';
709	            default:
710	                return '0';
711	        }
712	    }
713	
714	    /**
715	     * City -> canonical region, the fixed ground truth for deriving locality.
716	     */
717	    private static final Map<String, String> CITY_REGION = Map.of(
718	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
719	
720	    /**
721	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
722	     * deriving locality from the postcode ahead of the city.
723	     */
724	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
725	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
726	
727	    /**
728	     * The owner's locality: the canonical region resolved by the postcode range first
729	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
730	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
731	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
732	     * when the city is not in the table either. The postcode takes precedence so cities that share a
733	     * name are disambiguated by their postcode's region.
734	     *
735	     * @return the canonical region string, or {@code "UNKNOWN"}
736	     */
737	    public String getLocality() {
738	        String byPostcode = regionForPostcode(this.postcode);
739	        if (byPostcode != null) {
740	            return byPostcode;
741	        }
742	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
743	    }
744	
745	    /**
746	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
747	     * its locality.
748	     */
749	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
750	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
751	
752	    /**
753	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
754	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
755	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
756	     * (e.g. {@code "UNKNOWN"}).
757	     *
758	     * @return the IANA timezone name, or {@code null}
759	     */
760	    public String getTimezone() {
761	        return REGION_TIMEZONE.get(getLocality());
762	    }
763	
764	    /**
765	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
766	     * absent, not a 4-digit number, or in no known range.
767	     *
768	     * @param postcode the owner's postcode (may be {@code null})
769	     * @return the matching region, or {@code null}
770	     */
771	    private static String regionForPostcode(String postcode) {
772	        if (postcode == null || !postcode.matches("\\d{4}")) {
773	            return null;
774	        }
775	        int value = Integer.parseInt(postcode);
776	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
777	            int[] range = entry.getValue();
778	            if (value >= range[0] && value <= range[1]) {
779	                return entry.getKey();
780	            }
781	        }
782	        return null;
783	    }
784	
785	    protected Set<Pet> getPetsInternal() {
786	        if (this.pets == null) {
787	            this.pets = new HashSet<>();
788	        }
789	        return this.pets;
790	    }
791	
792	    protected void setPetsInternal(Set<Pet> pets) {
793	        this.pets = pets;
794	    }
795	
796	    public List<Pet> getPets() {
797	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
798	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
799	        return Collections.unmodifiableList(sortedPets);
800	    }
801	
802	    public void setPets(List<Pet> pets) {
803	        this.pets = new HashSet<>(pets);
804	    }
805	
806	    public void addPet(Pet pet) {
807	        getPetsInternal().add(pet);
808	        pet.setOwner(this);
809	    }
810	
811	    /**
812	     * Return the Pet with the given name, or null if none found for this Owner.
813	     *
814	     * @param name to test
815	     * @return true if pet name is already in use
816	     */
817	    public Pet getPet(String name) {
818	        return getPet(name, false);
819	    }
820	
821	    /**
822	     * Return the Pet with the given name, or null if none found for this Owner.
823	     *
824	     * @param name to test
825	     * @return true if pet name is already in use
826	     */
827	    public Pet getPet(String name, boolean ignoreNew) {
828	        name = name.toLowerCase();
829	        for (Pet pet : getPetsInternal()) {
830	            if (!ignoreNew || !pet.isNew()) {
831	                String compName = pet.getName();
832	                compName = compName.toLowerCase();
833	                if (compName.equals(name)) {
834	                    return pet;
835	                }
836	            }
837	        }
838	        return null;
839	    }
840	
841	    public Pet getPet(Integer petId) {
842	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
843	    }
844	
845	    @Override
846	    public String toString() {
847	        return new ToStringCreator(this)
848	
849	            .append("id", this.getId())
850	            .append("new", this.isNew())
851	            .append("lastName", this.getLastName())
852	            .append("firstName", this.getFirstName())
853	            .append("address", this.address)
854	            .append("city", this.city)
855	            .append("telephone", this.telephone)
856	            .append("email", this.email)
857	            .toString();
858	    }
859	}
